from pathlib import Path
import unittest,json,traceback,sys,hashlib,datetime
import blank21_browser as original
R=Path(__file__).parent
SNAP=r'''()=>{const e=document.querySelector('#file-handoff-preview > summary');const node=a=>{if(!a)return null;const s=getComputedStyle(a),r=a.getBoundingClientRect(),sx=a.offsetWidth?r.width/a.offsetWidth:1,sy=a.offsetHeight?r.height/a.offsetHeight:1;return {id:a.id,tag:a.tagName,class:a.className,rect:r.toJSON(),clientRects:[...a.getClientRects()].map(r=>r.toJSON()),clientBox:{left:r.left+a.clientLeft*sx,top:r.top+a.clientTop*sy,right:r.left+(a.clientLeft+a.clientWidth)*sx,bottom:r.top+(a.clientTop+a.clientHeight)*sy},clientLeft:a.clientLeft,clientTop:a.clientTop,clientWidth:a.clientWidth,clientHeight:a.clientHeight,offsetWidth:a.offsetWidth,offsetHeight:a.offsetHeight,scrollLeft:a.scrollLeft,scrollTop:a.scrollTop,scrollWidth:a.scrollWidth,scrollHeight:a.scrollHeight,style:{overflowX:s.overflowX,overflowY:s.overflowY,clipPath:s.clipPath,clip:s.clip,visibility:s.visibility,display:s.display,contentVisibility:s.contentVisibility,contain:s.contain,transform:s.transform,position:s.position,scrollBehavior:s.scrollBehavior},scale:[sx,sy]}};const ancestors=[];for(let a=e;a;a=a.parentElement)ancestors.push(node(a));const r=e?.getBoundingClientRect();const points=r?[['center',r.x+r.width/2,r.y+r.height/2],['topLeft',r.x+1,r.y+1],['bottomRight',r.right-1,r.bottom-1]].map(([name,x,y])=>{const h=document.elementFromPoint(x,y);return {name,x,y,hit:node(h),targetOrDescendant:!!h&&(h===e||e.contains(h))}}):[];const text=[];if(e){const w=document.createTreeWalker(e,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){const range=document.createRange();range.selectNodeContents(n);text.push({text:n.data,rect:range.getBoundingClientRect().toJSON(),rects:[...range.getClientRects()].map(r=>r.toJSON())})}}return {time:performance.now(),utc:new Date().toISOString(),summaryPresent:!!e,summaryText:e?.textContent,detailsOpen:e?.parentElement.open,ancestors,text,points,activeElement:{node:node(document.activeElement),outerHTML:document.activeElement?.outerHTML.slice(0,1500),isSummary:document.activeElement===e},window:{scrollX,scrollY,innerWidth,innerHeight,outerWidth,outerHeight,devicePixelRatio},visualViewport:visualViewport?{width:visualViewport.width,height:visualViewport.height,offsetLeft:visualViewport.offsetLeft,offsetTop:visualViewport.offsetTop,pageLeft:visualViewport.pageLeft,pageTop:visualViewport.pageTop,scale:visualViewport.scale}:null,document:{readyState:document.readyState,visibilityState:document.visibilityState,scrollingElement:node(document.scrollingElement),documentElement:node(document.documentElement),body:node(document.body)}}}'''
FRESH_IO=r'''()=>new Promise(resolve=>{const e=document.querySelector('#file-handoff-preview > summary');if(!e){resolve({missing:true});return}let done=false;const finish=x=>{if(done)return;done=true;clearTimeout(timer);io.disconnect();resolve(x)},io=new IntersectionObserver(es=>{finish({observedAt:performance.now(),sameDOMIdentity:document.querySelector('#file-handoff-preview > summary')===e,entries:es.map(a=>({time:a.time,isIntersecting:a.isIntersecting,intersectionRatio:a.intersectionRatio,boundingClientRect:a.boundingClientRect.toJSON(),intersectionRect:a.intersectionRect.toJSON(),rootBounds:a.rootBounds?.toJSON(),isTarget:a.target===e})),atCallback:{windowY:scrollY,activeIsSummary:document.activeElement===e,open:e.parentElement.open,rect:e.getBoundingClientRect().toJSON()}})},{root:null,threshold:[0,0.001,1]});const timer=setTimeout(()=>finish({missing:true,reason:'fresh IO callback deadline after failure only'}),5000);io.observe(e)})'''
class AfterFailureOnly(unittest.TextTestResult):
 def addFailure(self,test,err):
  super().addFailure(test,err) # Original assertion has failed, and unittest has recorded it.
  self.capture(test,err,'failure')
 def addError(self,test,err):
  super().addError(test,err);self.capture(test,err,'error')
 def capture(self,test,err,kind):
  data={'UTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'hook':'unittest result.addFailure after super; before original tearDown','test':test.id(),'kind':kind,'originalException':''.join(traceback.format_exception(*err))}
  try:
   data['snapshotBeforeFreshIO']=test.page.evaluate(SNAP)
   data['freshIntersectionObserver']=test.page.evaluate(FRESH_IO)
   data['snapshotAfterFreshIO']=test.page.evaluate(SNAP)
   test.page.screenshot(path=str(R/'postfailure-before-original-teardown.png'))
  except Exception:data['observationError']=traceback.format_exc()
  (R/'postfailure.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
if __name__=='__main__':
 digest=hashlib.sha256((R/'blank21_browser.py').read_bytes()).hexdigest();assert digest=='212163b1f4b7b6e328bc194676656eaed570a65179c6670dc6274e74d10a3117'
 suite=unittest.TestSuite([original.Blank21('test_first_handoff_choice_and_long_read_return')]);r=unittest.TextTestRunner(verbosity=2,resultclass=AfterFailureOnly).run(suite)
 (R/'result.json').write_text(json.dumps({'expected':1,'executed':r.testsRun,'failures':len(r.failures),'errors':len(r.errors),'originalCheckerSHA256':digest,'failureOnlyObservation':(R/'postfailure.json').exists(),'failureBeforeInstrumentation':True,'previousEvidenceUnchanged':True},indent=2));sys.exit(0 if r.wasSuccessful() and r.testsRun==1 else 1)
